              </TabList>
            </div>
            <Button view=\"outlined\" onClick={toggleTheme}>
              {theme === 'light' ? 'Тёмная тема' : 'Светлая тема'}
            </Button>
          </div>
        </header>
        <main className=\"app-content\">
          <div className=\"app-container\">{page}</div>
        </main>
      </div>
    </ThemeProvider>
  );
}
